/** Elements whose own arrow-key behaviour wins over stepping (fields, the split separator, sliders, radios,
 *  data-grid cells and keyboard-scrollable regions). */
export const ARROW_CONSUMERS =
  'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [role="separator"], [role="slider"], [role="radio"], [role="listbox"], [role="combobox"], [role="grid"] *, [role="region"][tabindex]'

export interface StepKey {
  key: string
  altKey: boolean
  ctrlKey: boolean
  metaKey: boolean
  shiftKey: boolean
  defaultPrevented: boolean
}

/** The step a key moves the simulation to, or null when the key is not for the simulation (or would not move). */
export function simStep(e: StepKey, target: { consumesArrows: boolean }, step: number, last: number): number | null {
  if (e.defaultPrevented || target.consumesArrows || e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return null
  const to = e.key === 'ArrowRight' ? step + 1 : e.key === 'ArrowLeft' ? step - 1 : e.key === 'Home' ? 0 : e.key === 'End' ? last : null
  if (to === null) return null
  const next = Math.max(0, Math.min(last, to))
  return next === step ? null : next
}
